/* Lessons for the documented OES hockey overlays and Nevco MPC code 871. */
function buildControllerCurriculum(profile){
 const lessons=[],nevco=profile==='nevco',legacy=profile==='isc85x';
 const add=(group,id,title,text,task,solution,predicate,setup=()=>{})=>lessons.push({group,id,title,text,task,solution,setup,check:(s,event,history)=>event!=='initial'&&predicate(s.model,event,history,s)});
 const pen=(player,remaining=120)=>({player,remaining});const seeded=(m)=>{m.pen.home=[pen(12)];};
 const key=(name,pred)=>(m,e)=>e==='key:'+name&&pred(m);
 const finish=(pred)=>(m,e)=>['key:enter','key:yes',...Array.from({length:10},(_,i)=>'key:'+i)].includes(e)&&!m.edit&&pred(m);
 if(nevco){
  add('Clock basics','startup','Start a wired hockey game','The training profile uses wired MPC operation. 871 is the hockey configuration code, not a console model number.','Practice setup → Power cycle → NO → NO → 871 → YES',['power','no','no','8','7','1','yes'],finish(m=>m.time===0&&m.home===0&&m.penaltyTimeout),s=>{s.model.home=4;});
  add('Clock basics','set-time','Set time and period','Use all five time digits: MMSS plus tenths. The period digit commits immediately.','SET → TIME → 15000 → YES → 1',['set','time','1','5','0','0','0','yes','1'],finish(m=>m.time===900&&m.period===1),s=>{s.model.time=600;});
  add('Clock basics','fraction','Set time with tenths','Put 45.3 seconds on the main clock. Leading zeroes matter.','SET → TIME → 00453 → YES → 1',['set','time','0','0','4','5','3','yes','1'],finish(m=>m.time===45.3));
  add('Clock basics','run-hold','Start at puck drop, stop on the whistle','With no handheld connected, TIME ON/OFF operates the main clock.','TIME ON → wait a moment → TIME OFF',['run','tick:1','hold'],key('hold',m=>!m.running&&m.time<900));
  add('Clock basics','cancel','Cancel an incorrect entry','NO cancels an unfinished edit without changing the original time.','SET → TIME → 9 → NO',['set','time','9','no'],key('no',m=>!m.edit&&m.time===900));
  add('Clock basics','expiry','Observe period end','Three seconds remain. The clock stops at zero and sounds the automatic horn.','TIME ON → wait for zero',['run','tick:4'],(m,e)=>e==='tick'&&m.time===0&&!m.running,s=>{s.model.time=3;});
  for(const side of ['home','guest']){
   const S=side.toUpperCase();
   add('Scores & shots','goal-'+side,`Add a ${side} goal`,'SCORE opens add mode. A number adds that amount immediately; GOAL controls an indicator instead.',`${S} SCORE → 1`,['score:'+side,'1'],finish(m=>m[side]===1));
   add('Scores & shots','score-'+side,`Correct the ${side} total`,'You cannot subtract in add mode. Use SET to enter the correct total.',`SET → ${S} SCORE → 2 → YES`,['set','score:'+side,'2','yes'],finish(m=>m[side]===2),s=>{s.model[side]=3;});
   add('Scores & shots','shot-'+side,`Add a ${side} shot`,'SHOTS works like score add mode; enter one to add one shot.',`${S} SHOTS → 1`,['shots:'+side,'1'],finish(m=>m.shots[side]===1));
   add('Scores & shots','shot-correct-'+side,`Correct ${side} shots`,'SET selects direct entry of the total.',`SET → ${S} SHOTS → 7 → YES`,['set','shots:'+side,'7','yes'],finish(m=>m.shots[side]===7),s=>{s.model.shots[side]=8;});
   add('Scores & shots','indicator-'+side,`Toggle the ${side} goal light`,'GOAL toggles the light indicator; it does not add to the score.',`${S} GOAL`,['goal:'+side],key('goal:'+side,m=>m.goal[side]&&m[side]===0));
   add('Penalties','minor-'+side,`Enter a ${side} minor`,'Enter duration first, then two jersey digits. The two-digit jersey completes entry.',`SET → ${S} PENALTY → 0200 → YES → 12`,['set','penalty:'+side,'0','2','0','0','yes','1','2'],finish(m=>m.pen[side].some(p=>p.player===12&&p.remaining===120)));
   add('Penalties','clear-'+side,`Release a ${side} penalty`,'Recall the penalty and confirm CLEAR. A goal never removes a penalty automatically.',`${S} PENALTY → PENALTY CLEAR → YES`,['penalty:'+side,'penClear','yes'],finish(m=>m.pen[side].length===0),s=>{s.model.pen[side]=[pen(12)];});
  }
  add('Penalties','jersey-blank','Enter a single-digit jersey','Use Blank for the leading position of a two-digit jersey number.','SET → HOME PENALTY → 0200 → YES → BLANK → 9',['set','penalty:home','0','2','0','0','yes','blank','9'],finish(m=>m.pen.home[0]?.player===9));
  add('Penalties','select','Select the second penalty','Each press cycles through this team’s penalty list. Keep #12; release #22.','HOME PENALTY × 2 → PENALTY CLEAR → YES',['penalty:home','penalty:home','penClear','yes'],finish(m=>m.pen.home.length===1&&m.pen.home[0].player===12),s=>{s.model.pen.home=[pen(12),pen(22)];});
  add('Penalties','edit','Correct penalty duration','Review #12, confirm EDIT, and change the remaining time to 1:30.','HOME PENALTY → PENALTY EDIT → YES → 0130 → YES',['penalty:home','penEdit','yes','0','1','3','0','yes'],finish(m=>m.pen.home[0]?.remaining===90),s=>seeded(s.model));
  add('Penalties','insert','Insert before a recalled penalty','Insert #22 for one minute ahead of the prepared #12 penalty.','HOME PENALTY → PENALTY INSERT → YES → 0100 → YES → 22',['penalty:home','penInsert','yes','0','1','0','0','yes','2','2'],finish(m=>m.pen.home.length===2&&m.pen.home[0].player===22&&m.pen.home[1].player===12),s=>seeded(s.model));
  add('Penalties','freeze','Pause penalty timing','Penalty time out was enabled at startup in this scenario. Freeze the penalty while the main clock runs.','PENALTY ON/OFF → TIME ON → wait',['penToggle','run','tick:1'],(m,e)=>e==='tick'&&!m.penRunning&&m.time<900&&m.pen.home[0].remaining===120,s=>seeded(s.model));
  add('Penalties','resume','Restore penalty timing','A penalty is prepared with penalty timing off. Enable it before play.','PENALTY ON/OFF → TIME ON → wait',['penToggle','run','tick:1'],(m,e)=>e==='tick'&&m.penRunning&&m.pen.home[0]?.remaining<120,s=>{seeded(s.model);s.model.penRunning=false;});
  add('Penalties','queue','Observe queued penalty timing','Two active penalties precede #33. When #12 expires, #33 moves into the active pair.','TIME ON → wait three seconds',['run','tick:3'],(m,e)=>e==='tick'&&m.pen.home.length===2&&m.pen.home[1].player===33&&m.pen.home[1].remaining<120,s=>{s.model.pen.home=[pen(12,2),pen(22,60),pen(33)];});
  add('Timeout & display','timeout','Start timeout timer zero','Timer 0 is configured as 30 seconds with a warning at ten. It operates independently of main time.','TIME OUT TIMER START → 0',['timeoutStart','0'],key('0',m=>m.timeoutTime===30&&m.view==='timeout'&&!m.running));
  add('Timeout & display','timeout-clear','Advance to the warning portion','CLEAR ends the current portion; the first press jumps to the warning time rather than ending the whole timeout.','TIME OUT TIMER CLEAR',['timeoutClear'],key('timeoutClear',m=>m.timeoutTime===10&&m.warningDone),s=>{s.model.timeoutTime=30;s.model.view='timeout';});
  add('Timeout & display','timeout-expiry','Observe overtime after a timeout','At zero the timeout counts upward on the console. It does not restart game time.','Wait four seconds',['tick:4'],(m,e)=>e==='tick'&&m.timeoutTime===0&&m.timeoutElapsed>0&&!m.running,s=>{s.model.timeoutTime=3;s.model.warningDone=true;s.model.view='timeout';});
  add('Timeout & display','return','Resume game time after a timeout','TIME ON cancels the timeout and restores the main time display.','TIME ON',['run'],key('run',m=>m.timeoutTime===null&&m.view==='game'&&m.running),s=>{s.model.timeoutTime=20;s.model.view='timeout';});
  add('Timeout & display','chrono','View the chronometer','This profile enables the time-of-day display. Game data is preserved.','CHRONOMETER',['chrono'],key('chrono',m=>m.view==='time'&&m.time===900));
  add('Timeout & display','main-display','Return to main time','TIME recalls the main time display.','TIME',['time'],key('time',m=>m.view==='game'&&m.time===900),s=>{s.model.view='time';});
  add('Horn & remote','auto-off','Disable the automatic horn','SET HORN opens a yes/no setting. Manual horn remains available.','SET → HORN → NO',['set','horn','no'],key('no',m=>!m.autoHorn));
  add('Horn & remote','auto-on','Enable the automatic horn','Restore end-of-period signals.','SET → HORN → YES',['set','horn','yes'],key('yes',m=>m.autoHorn),s=>{s.model.autoHorn=false;});
  add('Horn & remote','remote','Use a handheld time switch','Connecting the handheld disables panel TIME ON/OFF. Use the separate practice switch.','Practice setup → Connect handheld → Handheld RUN/STOP',['remote','remoteRun'],key('remoteRun',m=>m.remote&&m.running));
  add('Horn & remote','options','Read the controller settings','OPTIONS reports this simulator’s selected configuration. Hardware configuration and bookmarks are outside this profile.','OPTIONS',['options'],key('options',m=>m.message.includes('CODE 871')));
 }else{
  add('Clock basics','time','Set game time','OES edits minutes, seconds and hundredths separately. Stop all timers before entry.','GAME TIME → 15 → ENTER → 0 → ENTER → 0 → ENTER',['set','1','5','enter','0','enter','0','enter'],finish(m=>m.time===900),s=>{s.model.time=600;});
  add('Clock basics','fraction','Correct time to a fraction','Enter 00:45.25 using the hundredths field.','GAME TIME → 0 → ENTER → 45 → ENTER → 25 → ENTER',['set','0','enter','4','5','enter','2','5','enter'],finish(m=>m.time===45.25));
  add('Clock basics','run-stop','Run and stop play',legacy?'Use the right-side rocker switch.':'Use the separate RUN and STOP keys.','RUN → wait a moment → STOP',['run','tick:1','hold'],key('hold',m=>!m.running&&m.time<900));
  add('Clock basics','stop-first','Editing requires a stopped clock','GAME TIME while running cannot change the time. Stop, then open the editing cursor.','RUN → GAME TIME → STOP → GAME TIME',['run','set','hold','set'],key('set',m=>!m.running&&m.edit?.type==='minutes'));
  add('Clock basics','period','Set the period number','Set period 2 directly. This does not reload time.','PERIOD → 2 → ENTER',['period','2','enter'],finish(m=>m.period===2&&m.time===900));
  add('Clock basics','next-period','Reload after period end','At zero, GAME TIME recalls the last set duration and advances the period.','GAME TIME → ENTER × 3',['set','enter','enter','enter'],finish(m=>m.time===900&&m.period===2),s=>{s.model.time=0;});
  add('Clock basics','expiry','Observe period-end behavior','Three seconds remain. Observe the automatic stop and horn.','RUN → wait for zero',['run','tick:4'],(m,e)=>e==='tick'&&m.time===0&&!m.running,s=>{s.model.time=3;});
  add('Clock basics','clear','Clear an incorrect numeric entry','CLEAR sets the selected field to zero. Type the replacement and confirm.','PERIOD → 9 → CLEAR → 2 → ENTER',['period','9','clear','2','enter'],finish(m=>m.period===2));
  for(const side of ['home','guest']){
   const S=side==='guest'&&legacy?'VISITOR':side.toUpperCase();
   add('Scores & shots','score-'+side,`Set the ${side} score`,'Enter the correct total directly, including corrections.',`${S} SCORE → 3 → ENTER`,['score:'+side,'3','enter'],finish(m=>m[side]===3));
   add('Scores & shots','goal-'+side,`Add a ${side} goal`,legacy?'Select the team score, then use +1.':'Use the dedicated SCORE +1 key.',legacy?`${S} SCORE → +1`:`${S} SCORE +1`,legacy?['score:'+side,'increment']:['scoreAdd:'+side],key(legacy?'increment':'scoreAdd:'+side,m=>m[side]===1));
   add('Scores & shots','shots-'+side,`Correct ${side} shots`,'Enter a shot total directly while stopped.',`${S} SHOTS → 7 → ENTER`,['shots:'+side,'7','enter'],finish(m=>m.shots[side]===7));
   add('Scores & shots','shot-'+side,`Add a ${side} shot`,legacy?'While game time runs, the team SHOTS key increments the total.':'Use the dedicated SHOTS +1 key.',legacy?`RUN → ${S} SHOTS`:`${S} SHOTS +1`,legacy?['run','shots:'+side]:['shotsAdd:'+side],key(legacy?'shots:'+side:'shotsAdd:'+side,m=>m.shots[side]===1));
   add('Penalties','minor-'+side,`Enter a ${side} minor`,'The first press selects an empty row. Enter jersey, minutes and seconds; finish all fields before RUN.',`${S} PENALTY → 12 → ENTER → 2 → ENTER → ENTER`,['penalty:'+side,'1','2','enter','2','enter','enter'],finish(m=>m.pen[side].some(p=>p?.player===12&&p.remaining===120)));
   add('Penalties','clear-'+side,`Release a ${side} penalty`,'First press selects the next empty row. Press again until the prepared penalty is selected.',`${S} PENALTY × 4 → CLEAR${legacy?' → CLEAR':''}`,['penalty:'+side,'penalty:'+side,'penalty:'+side,'penalty:'+side,'clear',...(legacy?['clear']:[])],key('clear',m=>m.pen[side].filter(Boolean).length===0),s=>{s.model.pen[side]=[pen(12)];});
  }
  add('Penalties','edit','Correct penalty time','Cycle to the prepared #12 row, accept its jersey and change its remaining time to 1:30.','HOME PENALTY × 4 → ENTER → 1 → ENTER → 30 → ENTER',['penalty:home','penalty:home','penalty:home','penalty:home','enter','1','enter','3','0','enter'],finish(m=>m.pen.home[0]?.remaining===90),s=>seeded(s.model));
  add('Penalties','queued','Enter a third penalty','Two penalties are prepared. #33 waits in row 3 and does not count while rows 1 and 2 are active.','HOME PENALTY → 33 → ENTER → 2 → ENTER → ENTER → RUN → wait',['penalty:home','3','3','enter','2','enter','enter','run','tick:1'],(m,e)=>e==='tick'&&m.pen.home[2]?.player===33&&m.pen.home[2].remaining===120,s=>{s.model.pen.home=[pen(12),pen(22)];});
  add('Penalties','release','Observe queued penalty release','When #12 expires, #33 moves into an active row and begins counting.','RUN → wait three seconds',['run','tick:3'],(m,e)=>e==='tick'&&m.pen.home[1]?.player===33&&m.pen.home[1].remaining<120,s=>{s.model.pen.home=[pen(12,2),pen(22,60),pen(33)];});
  add('Break & shift','intermission','Set an intermission','INT MODE has its own minutes and seconds; penalties stay frozen.','INT MODE → 1 → ENTER → 0 → ENTER → RUN',['intermission','1','enter','0','enter','run'],key('run',m=>m.view==='break'&&m.breakTime===60&&m.time===900&&m.pen.home[0].remaining===120),s=>seeded(s.model));
  add('Break & shift','return','Return to game mode','Stop the intermission, then press INT MODE again. Main game time is preserved.','STOP → INT MODE',['hold','intermission'],key('intermission',m=>m.view==='game'&&m.time===900),s=>{s.model.view='break';s.model.breakTime=60;s.model.running=true;});
  add('Break & shift','break-expiry','Observe break expiry','The break stops at zero and stays in INT MODE until you exit.','Wait four seconds',['tick:4'],(m,e)=>e==='tick'&&!m.running&&m.view==='break'&&m.breakTime===0,s=>{s.model.view='break';s.model.breakTime=3;s.model.running=true;});
  add('Break & shift','shift','Set a repeating shift horn','Shift timing is enabled in this training configuration. It runs with game time and repeats after sounding.',legacy?'SHIFT → 1 → ENTER':'SHIFT → 1 → ENTER → 0 → ENTER',legacy?['shift','1','enter']:['shift','1','enter','0','enter'],finish(m=>m.shiftSet===60&&m.shiftTime===60));
  add('Break & shift','shift-expiry','Observe a repeating shift','Three seconds remain on a one-minute shift. The horn sounds and the shift reloads without stopping play.','RUN → wait four seconds',['run','tick:4'],(m,e)=>e==='tick'&&m.running&&m.shiftTime===59,s=>{s.model.shiftSet=60;s.model.shiftTime=3;});
  add('Break & shift','shift-off','Disable shift timing','Set the shift duration to zero to disable its repeating horn.',legacy?'SHIFT → 0 → ENTER':'SHIFT → 0 → ENTER → 0 → ENTER',legacy?['shift','0','enter']:['shift','0','enter','0','enter'],finish(m=>m.shiftSet===0),s=>{s.model.shiftSet=s.model.shiftTime=60;});
  if(legacy){
   for(const minutes of [2,5,10,20])add('ISC85X controls','preset-'+minutes,`Add ${minutes} minutes with a preset`,'Time preset keys ADD minutes to the selected value; they do not replace it.',`GAME TIME → ${minutes}:00 → ENTER × 3`,['set','preset:'+minutes,'enter','enter','enter'],finish(m=>m.time===(15+minutes)*60));
   add('ISC85X controls','increment-period','Increment the period','Select PERIOD before using the shared +1 key.','PERIOD → +1',['period','increment'],key('increment',m=>m.period===2));
   add('ISC85X controls','count-up','Use count-up mode','Select UP, confirm, then enter a one-minute stop limit.','TIME UP/DOWN → ENTER → 1 → ENTER → RUN',['direction','enter','1','enter','run'],key('run',m=>!m.down&&m.limit===60&&m.time===0&&m.running));
   add('ISC85X controls','count-down','Restore count-down mode','The prepared timer counts up. Toggle direction back to DOWN.','TIME UP/DOWN',['direction'],key('direction',m=>m.down),s=>{s.model.down=false;});
  }else{
   add('ISC9000 controls','period-increment','Increment the period with two presses','PERIOD twice increments without typing a new value.','PERIOD × 2',['period','period'],key('period',m=>m.period===2&&!m.edit));
   add('ISC9000 controls','pen-stop','Stop penalty clocks only','The main game clock continues while the prepared penalty stays frozen.','PENALTY STOP/RUN → RUN → wait',['penrun','run','tick:1'],(m,e)=>e==='tick'&&!m.penRunning&&m.time<900&&m.pen.home[0].remaining===120,s=>seeded(s.model));
   add('ISC9000 controls','pen-run','Resume penalty clocks','Toggle penalty timing back to RUN.','PENALTY STOP/RUN → RUN → wait',['penrun','run','tick:1'],(m,e)=>e==='tick'&&m.penRunning&&m.pen.home[0]?.remaining<120,s=>{seeded(s.model);s.model.penRunning=false;});
   add('ISC9000 controls','queue-hold','Hold queued penalties','HOLD prevents rows 3 and 4 from shifting into active positions after an expiry.','PENALTY HOLD → RUN → wait three seconds',['penhold','run','tick:3'],(m,e)=>e==='tick'&&m.holdQueue&&m.pen.home[2]?.remaining===120,s=>{s.model.pen.home=[pen(12,2),pen(22,60),pen(33)];});
   add('ISC9000 controls','queue-release','Release held queue rows','Turn off HOLD to allow the waiting penalty to move into an active position.','PENALTY HOLD',['penhold'],key('penhold',m=>!m.holdQueue&&m.pen.home[1]?.player===33),s=>{s.model.holdQueue=true;s.model.pen.home=[null,pen(22),pen(33)];});
   add('ISC9000 controls','saved','Restore last-stoppage times','A saved stoppage at 14:30 is prepared. Hold SAVED TIME for one second to restore both game and penalty time.','Press and hold SAVED TIME',['saved'],key('saved',m=>m.time===870&&m.pen.home[0]?.remaining===90),s=>{s.model.saved={time:870,pen:{home:[pen(12,90)],guest:[]}};s.model.time=800;});
   add('ISC9000 controls','names','Set team names with the keypad','Repeated presses cycle letters. The four fields are home full, home short, guest full, guest short. Enter moves to the next name.','TEAM NAME → 2 twice (B) → ENTER × 2 → 3 (D) → ENTER × 2',['names','2','2','enter','enter','3','enter','enter'],finish(m=>m.names.home==='B'&&m.names.guest==='D'));
   add('ISC9000 controls','status','Read the active configuration','STATUS reports the fixed hockey configuration used in this trainer. Physical installation settings are outside its scope.','STATUS',['status'],key('status',m=>m.message.includes('4 PENALTIES')));
  }
 }
 add('Sound & practice','horn','Sound the manual horn','Use the physical horn key. Sound starts on; check your device volume if needed.','Press and hold HORN',['horn'],(m,e,a,s)=>e==='key:horn'&&s.sound&&!m.edit);
 add('Sound & practice','mute','Mute simulator audio','The sound switch controls this browser session.','Tap Sound on',['ui:sound'],(m,e,a,s)=>e==='ui:sound'&&!s.sound);
 add('Sound & practice','speed','Use accelerated practice','Open Practice setup and select 5×. All simulated timers accelerate together.','Practice setup → Simulation speed → 5×',['ui:speed:5'],(m,e,a,s)=>e==='ui:speed'&&s.speed===5);
 add('Sound & practice','reset','Reset a practice game','Reset clears the prepared scores and penalties. The hardware power sequence is separate.','Practice setup → Reset game → confirm',['ui:reset'],(m,e)=>e==='ui:reset'&&m.home===0&&m.pen.home.length===0,s=>{s.model.home=3;seeded(s.model);});
 add('Sound & practice','reference','Compare with the real controller','Open the photo and source notes. Check the panel layout and read the listed configuration limits.','Expand Controller photo & manual',['ui:reference'],(m,e)=>e==='ui:reference');
 return lessons;
}
if(typeof module!=='undefined')module.exports=buildControllerCurriculum;
else {const earlierCurriculum=buildCurriculum;buildCurriculum=profile=>['nevco','isc9000','isc85x'].includes(profile)?buildControllerCurriculum(profile):earlierCurriculum(profile);}
